        font-size: 14px;
        box-shadow: 0 2px 5px rgba(0,0,0,0.1);
    }
    .hacamat-table th {
        background-color: #2c3e50; /* Koyu gri/mavi tonu */
        color: white;
        padding: 12px;
        text-align: left;
        border: 1px solid #ddd;
    }
    .hacamat-table td {
        padding: 10px;
        border: 1px solid #ddd;
    }
    .hacamat-table tr:nth-child(even) {
        background-color: #f9f9f9; /* Satırları ayırt etmek için açık gri */
    }
    .hacamat-table tr:hover {
        background-color: #f1f1f1; /* Mouse ile üzerine gelince renk değişimi */
    }
    .feature-title {
        color: #e67e22; /* Özellik başlıkları için turuncu tonu */
        font-weight: bold;
    }


